ALTER TABLE event_banner_config ADD COLUMN IF NOT EXISTS slug TEXT, ADD COLUMN IF NOT EXISTS short_description_en TEXT, ADD COLUMN IF NOT EXISTS short_description_tr TEXT, ADD COLUMN IF NOT EXISTS full_description_en TEXT, ADD COLUMN IF NOT EXISTS full_description_tr TEXT, ADD COLUMN IF NOT EXISTS booking_open_at TIMESTAMPTZ, ADD COLUMN IF NOT EXISTS booking_close_at TIMESTAMPTZ, ADD COLUMN IF NOT EXISTS currency TEXT NOT NULL DEFAULT 'TRY', ADD COLUMN IF NOT EXISTS location_type TEXT NOT NULL DEFAULT 'in_person', ADD COLUMN IF NOT EXISTS private_location TEXT, ADD COLUMN IF NOT EXISTS city TEXT NOT NULL DEFAULT 'Istanbul', ADD COLUMN IF NOT EXISTS country TEXT NOT NULL DEFAULT 'Türkiye', ADD COLUMN IF NOT EXISTS recap_text_en TEXT, ADD COLUMN IF NOT EXISTS recap_text_tr TEXT, ADD COLUMN IF NOT EXISTS featured BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN IF NOT EXISTS completed_at TIMESTAMPTZ, ADD COLUMN IF NOT EXISTS public_archive BOOLEAN NOT NULL DEFAULT TRUE, ADD COLUMN IF NOT EXISTS show_attendee_count BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN IF NOT EXISTS photo_consent_confirmed BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN IF NOT EXISTS seo_title TEXT, ADD COLUMN IF NOT EXISTS seo_description TEXT;
UPDATE event_banner_config SET slug=COALESCE(NULLIF(slug,''),id), short_description_en=COALESCE(short_description_en,description_en), short_description_tr=COALESCE(short_description_tr,description_tr), full_description_en=COALESCE(full_description_en,secondary_details_en,description_en), full_description_tr=COALESCE(full_description_tr,secondary_details_tr,description_tr), booking_close_at=COALESCE(booking_close_at,display_end_at,event_start_at);
CREATE UNIQUE INDEX IF NOT EXISTS event_banner_slug_unique ON event_banner_config(slug);
ALTER TABLE event_applications ADD COLUMN IF NOT EXISTS registration_status TEXT NOT NULL DEFAULT 'pending', ADD COLUMN IF NOT EXISTS attendance_status TEXT NOT NULL DEFAULT 'unknown', ADD COLUMN IF NOT EXISTS gender TEXT, ADD COLUMN IF NOT EXISTS attended_at TIMESTAMPTZ;
UPDATE event_applications SET registration_status=CASE WHEN status IN ('accepted','attended') THEN 'approved' WHEN status IN ('pending','waitlisted','rejected','cancelled') THEN status ELSE 'pending' END, attendance_status=CASE WHEN status='attended' THEN 'attended' ELSE attendance_status END;
CREATE TABLE IF NOT EXISTS event_gallery_images (id UUID PRIMARY KEY,event_id TEXT NOT NULL REFERENCES event_banner_config(id) ON DELETE CASCADE,image_url TEXT NOT NULL,alt_text TEXT NOT NULL,caption TEXT,orientation TEXT NOT NULL DEFAULT 'landscape',display_order INTEGER NOT NULL DEFAULT 1,is_cover BOOLEAN NOT NULL DEFAULT FALSE,is_private BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS event_review_invitations (id UUID PRIMARY KEY,event_id TEXT NOT NULL REFERENCES event_banner_config(id) ON DELETE CASCADE,attendee_id UUID NOT NULL REFERENCES event_applications(id) ON DELETE CASCADE,token_hash TEXT UNIQUE NOT NULL,expires_at TIMESTAMPTZ NOT NULL,used_at TIMESTAMPTZ,revoked_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(event_id,attendee_id));
CREATE TABLE IF NOT EXISTS event_reviews (id UUID PRIMARY KEY,event_id TEXT NOT NULL REFERENCES event_banner_config(id) ON DELETE CASCADE,attendee_id UUID NOT NULL REFERENCES event_applications(id) ON DELETE CASCADE,invitation_id UUID UNIQUE NOT NULL REFERENCES event_review_invitations(id) ON DELETE CASCADE,display_name TEXT NOT NULL,rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),comment TEXT NOT NULL,original_display_name TEXT NOT NULL,original_comment TEXT NOT NULL,public_display_consent BOOLEAN NOT NULL,status TEXT NOT NULL DEFAULT 'pending',moderation_note TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
ALTER TABLE event_banner_config DROP CONSTRAINT IF EXISTS event_banner_config_status_check;
ALTER TABLE event_banner_config ADD CONSTRAINT event_banner_config_status_check CHECK (status IN ('draft','scheduled','booking_open','fully_booked','booking_closed','active','paused','expired','completed','cancelled','archived'));
